package com.phantasia.core.logic;

import com.phantasia.core.data.*;
import com.phantasia.core.model.*;
import com.phantasia.core.world.*;
import com.phantasia.j2d.diagnostic.*;
import com.phantasia.j2d.engine.*;
import com.phantasia.j2d.screen.*;
import java.awt.Canvas;
import java.awt.event.KeyEvent;
import java.awt.image.BufferedImage;
import java.nio.file.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Predicate;

/** Uses package-private dice seams; public gameplay still rolls the established chance. */
public final class NativeEscapeSmokeTest {
    private static int checks;
    private static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
    private static void same(Object a,Object b,String text){check(Objects.equals(a,b),text+": "+a+" != "+b);}
    private static void rejects(Runnable action,String text){try{action.run();throw new AssertionError(text);}catch(IllegalArgumentException|IllegalStateException expected){check(true,text);}}
    private static PlayerRuntimeV5 player(String name,int hp,int agility){return new PlayerRuntimeV5(PlayerCreationV5.create(name,1,Job.WIZARD,0,20,agility,20,hp,10));}
    private static Monster enemy(int hp){return EncounterFactory.buildMonster("Escape foe",hp,1,40);}
    private static CombatRoundV5 round(List<PlayerRuntimeV5> party,List<Monster> enemies,int enemySpeed,Predicate<PlayerRuntimeV5> escape){return new CombatRoundV5(party,enemies,Map.of(),Map.of(),actor->actor instanceof PlayerRuntimeV5 p?p.attribute(PlayerStateV5.Attribute.AGILITY):enemySpeed,(p,m)->true,(m,p)->true,m->10,(p,m)->true,(p,m)->true,escape);}
    private static long attempts(RoundResult r){return r.events().stream().filter(e->e instanceof CombatEvent.FleeAttempt).count();}
    public static void main(String[] args)throws Exception{chancesAndContracts();successAndFailure();initiativeAndInactivity();campaign();screens();System.out.println("NATIVE_ESCAPE checks="+checks+" PASS");}
    private static void chancesAndContracts(){
        same(30,FormulaEngine.escapeChance(player("Slow",100,0)),"existing zero-Agility chance");same(50,FormulaEngine.escapeChance(player("Normal",100,20)),"existing normal chance");same(85,FormulaEngine.escapeChance(player("Cap",100,55)),"chance cap boundary");same(85,FormulaEngine.escapeChance(player("Fast",100,255)),"chance remains capped");
        var p=player("Runner",100,20);var e=enemy(100);rejects(()->new CombatRoundV5.PlayerOrder(p,Action.RUN,e,null,null,null),"run rejects enemy target");rejects(()->new CombatRoundV5.PlayerOrder(p,Action.RUN,null,p,null,null),"run rejects ally target");rejects(()->new CombatRoundV5.PlayerOrder(p,Action.RUN,null,null,null,CombatRank.FRONT),"run rejects rank payload");
        var combat=round(List.of(p),List.of(e),10,ignored->true);var outsider=player("Other",100,20);rejects(()->combat.runRound(List.of(CombatRoundV5.PlayerOrder.run(outsider))),"outsider cannot run for party");rejects(()->combat.runRound(List.of(CombatRoundV5.PlayerOrder.run(p),CombatRoundV5.PlayerOrder.parry(p))),"runner cannot take second action");same(100,p.hp(),"invalid orders no HP change");same(10,p.mp(),"invalid orders no MP change");same(1,combat.runRound(List.of(CombatRoundV5.PlayerOrder.run(p))).roundNumber(),"invalid plans do not advance round");
    }
    private static void successAndFailure(){
        var a=player("A",100,20);var b=player("B",100,18);var e=enemy(100);var rolls=new AtomicInteger();var combat=round(List.of(a,b),List.of(e),10,p->{rolls.incrementAndGet();return true;});
        var result=combat.runRound(List.of(CombatRoundV5.PlayerOrder.run(a),CombatRoundV5.PlayerOrder.attack(b,e,CombatRank.FRONT)));
        same(CombatOutcome.ESCAPED,result.outcome(),"successful run ends encounter");same(1L,attempts(result),"one attempt for acting runner");same(1,rolls.get(),"escape roll called once");check(result.events().stream().anyMatch(x->x instanceof CombatEvent.FleeAttempt f&&f.succeeded()),"success event emitted");check(result.events().stream().noneMatch(x->x instanceof CombatEvent.Hit),"later player/enemy hits stop");same(100,a.hp(),"runner takes no later retaliation");same(100,b.hp(),"companion HP preserved");same(100,e.getHp(),"later companion attack not executed");same(2,combat.partyMembers().size(),"party roster never shrinks");same(a,combat.partyMembers().get(0),"same native runner retained");same(b,combat.partyMembers().get(1),"same companion retained");check(new CombatNarrator().narrateRound(result).contains("The party escapes!"),"existing narrator reports party retreat");rejects(()->combat.runRound(List.of(CombatRoundV5.PlayerOrder.run(a))),"terminal escape cannot run another round");same(1,rolls.get(),"terminal rejection cannot reroll escape");
        var p=player("Retry",100,20);var foe=enemy(100);var calls=new AtomicInteger();var retry=round(List.of(p),List.of(foe),10,ignored->calls.incrementAndGet()>1);var first=retry.runRound(List.of(CombatRoundV5.PlayerOrder.run(p)));
        same(CombatOutcome.ONGOING,first.outcome(),"failed run keeps battle ongoing");same(1L,attempts(first),"failed attempt emitted once");same(90,p.hp(),"failed run permits enemy retaliation");same(100,foe.getHp(),"failed run gives no attack to runner");same(10,p.mp(),"run never spends MP");var second=retry.runRound(List.of(CombatRoundV5.PlayerOrder.run(p)));same(CombatOutcome.ESCAPED,second.outcome(),"later round may escape");same(2,second.roundNumber(),"retry spends another round action");same(90,p.hp(),"successful retry stops further retaliation");
        var x=player("First",100,20);var y=player("Second",100,20);var times=new AtomicInteger();var multiple=round(List.of(x,y),List.of(enemy(100)),10,ignored->times.incrementAndGet()==2);var both=multiple.runRound(List.of(CombatRoundV5.PlayerOrder.run(x),CombatRoundV5.PlayerOrder.run(y)));same(2L,attempts(both),"two distinct runners each get at most one attempt");same(CombatOutcome.ESCAPED,both.outcome(),"second runner may retreat the party");same(100,x.hp(),"no enemy turn after second success");same(100,y.hp(),"all members withdraw intact");
        var caster=player("Caster",100,18);var runner=player("Fast",100,20);var spellCore=new DataCore();spellCore.setName("Stop test");spellCore.setStat(DataLayout.SPELL_MP_COST,3);spellCore.setStat(DataLayout.SPELL_POWER,10);spellCore.setStat(DataLayout.SPELL_TARGET,Spell.TargetType.SINGLE_ENEMY.ordinal());spellCore.setStat(DataLayout.SPELL_EFFECT_TYPE,Spell.EffectType.DAMAGE.ordinal());var spell=new Spell(spellCore);var target=enemy(100);var noCast=round(List.of(runner,caster),List.of(target),10,ignored->true);var stopped=noCast.runRound(List.of(CombatRoundV5.PlayerOrder.run(runner),CombatRoundV5.PlayerOrder.cast(caster,spell,target,null)));same(10,caster.mp(),"escape stops later spell resource spending");check(stopped.events().stream().noneMatch(ev->ev instanceof CombatEvent.SpellCast),"no later spell event");
    }
    private static void initiativeAndInactivity(){
        var p=player("Slow",100,5);var combat=round(List.of(p),List.of(enemy(100)),20,ignored->true);var result=combat.runRound(List.of(CombatRoundV5.PlayerOrder.run(p)));same(CombatOutcome.ESCAPED,result.outcome(),"slower living runner may escape");same(90,p.hp(),"damage before runner's turn is retained");check(result.events().get(1) instanceof CombatEvent.Hit,"faster monster acts before run");
        var frail=player("Frail",5,5);var never=new AtomicInteger();var death=round(List.of(frail),List.of(enemy(100)),20,ignored->{never.incrementAndGet();return true;});var defeated=death.runRound(List.of(CombatRoundV5.PlayerOrder.run(frail)));same(CombatOutcome.DEFEAT,defeated.outcome(),"death before turn prevents escape");same(0,never.get(),"dead runner never rolls");same(0L,attempts(defeated),"dead runner emits no attempt");
        var sleeper=player("Asleep",100,20);sleeper.setAsleep(true);var sleeping=round(List.of(sleeper),List.of(enemy(100)),10,ignored->{throw new AssertionError("Sleeping runner rolled");});var slept=sleeping.runRound(List.of(CombatRoundV5.PlayerOrder.run(sleeper)));same(CombatOutcome.ONGOING,slept.outcome(),"sleep cannot retreat party");same(0L,attempts(slept),"sleeping run has no attempt");same(90,sleeper.hp(),"sleeping party still subject to enemy turn");
        var dead=player("Dead",1,20);dead.damage(1);var alive=player("Alive",100,18);var who=new ArrayList<String>();var sparse=round(List.of(dead,alive),List.of(enemy(100)),10,actor->{who.add(actor.name());return true;});sparse.runRound(List.of(CombatRoundV5.PlayerOrder.run(dead),CombatRoundV5.PlayerOrder.run(alive)));same(List.of("Alive"),who,"dead party member cannot supply an escape roll");same(2,sparse.partyMembers().size(),"dead record also retained after retreat");
        var killer=player("Killer",100,20);var runner=player("Runner",100,18);var victim=enemy(1);var victory=round(List.of(killer,runner),List.of(victim),10,ignored->{throw new AssertionError("Retreat after victory");});var won=victory.runRound(List.of(CombatRoundV5.PlayerOrder.attack(killer,victim,CombatRank.FRONT),CombatRoundV5.PlayerOrder.run(runner)));same(CombatOutcome.VICTORY,won.outcome(),"prior victory takes precedence over unperformed run");same(0L,attempts(won),"no attempt after enemy defeat");
    }
    private static void campaign(){
        var c=NativeProgressionScreen.freshCampaign();var party=c.party();var gold=c.gold();var bank=c.bankGold();var enemy=enemy(100);var battle=c.startBattle(List.of(enemy),ignored->10,ignored->true);var a=party.get(0);var b=party.get(1);battle.select(a,Action.RUN,null);battle.select(b,Action.PARRY,null);check(battle.canConfirm(),"run is available without learning/readied slots");rejects(()->battle.select(a,Action.RUN,enemy),"native selection rejects run target");same(Action.RUN,battle.rows().get(0).order().action(),"bad replacement keeps run plan");var result=battle.confirmRound();same(CombatOutcome.ESCAPED,result.outcome(),"native campaign resolves escape");var receipt=battle.settle();same(0L,receipt.experiencePool(),"escape awards zero XP");same(0L,receipt.gold(),"escape awards zero treasure");same(gold,c.gold(),"purse unchanged");same(bank,c.bankGold(),"bank unchanged");same(0L,c.pendingGold(),"escape queues no gold");same(0L,a.runtime().experience(),"runner no XP");same(0L,b.runtime().experience(),"companion no XP");same(party,c.party(),"campaign roster unchanged");same(receipt,battle.settle(),"escape receipt idempotent");rejects(c::snapshot,"escape result must be acknowledged before saving");rejects(()->c.ready(a,List.of()),"result still locks preparation");battle.acknowledge();same(null,c.activeBattle(),"acknowledgement releases campaign");check(c.snapshot()!=null,"outside-combat snapshot allowed after escape");var newer=c.startBattle(List.of(enemy(100)),ignored->10,ignored->true);battle.acknowledge();same(newer,c.activeBattle(),"stale acknowledgement cannot release new battle");
    }
    private static void key(ScreenManager manager,int code){var canvas=new Canvas();manager.getActiveScreen().onKeyPressed(new KeyEvent(canvas,KeyEvent.KEY_PRESSED,0,0,code,KeyEvent.CHAR_UNDEFINED));manager.update(.2f);manager.update(.2f);manager.getActiveScreen().onKeyReleased(new KeyEvent(canvas,KeyEvent.KEY_RELEASED,0,0,code,KeyEvent.CHAR_UNDEFINED));}
    private static void render(ScreenManager manager)throws Exception{var image=new BufferedImage(GameCanvas.DESIGN_WIDTH,GameCanvas.DESIGN_HEIGHT,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();try{manager.render(g,image.getWidth(),image.getHeight());}finally{g.dispose();}check(image.getRGB(80,80)!=0xff000000,"escape result renders");javax.imageio.ImageIO.write(image,"png",Path.of(System.getProperty("java.io.tmpdir"),"native-escape.png").toFile());}
    private static void screens()throws Exception{
        var content=DiagnosticContent.create();var c=NativeProgressionScreen.freshCampaign();var t=new LocalMapTraversal(content.maps(),c,DiagnosticContent.DUNGEON,null);var flow=new NativeLocalEncounterFlow(t,c,()->List.of(enemy(100)),ignored->10,ignored->true);var visit=new LocalMapScreen.Visit(t,GameState.WORLD_ROAM,null,flow);var manager=new ScreenManager();manager.register(GameState.NATIVE_LOCAL_MAP,new LocalMapScreen(manager,c,content.npcs(),content.shops(),()->List.of(enemy(100))));manager.register(GameState.NATIVE_DIAGNOSTIC,new NativeProgressionScreen(manager,c));manager.switchTo(GameState.NATIVE_LOCAL_MAP,visit);
        for(int i=0;i<6;i++)key(manager,KeyEvent.VK_RIGHT);same(GameState.NATIVE_DIAGNOSTIC,manager.getActiveState(),"map movement opens actual native battle");var pos=t.position();var facing=t.facing();var battle=c.activeBattle();key(manager,KeyEvent.VK_F);same(Action.RUN,battle.rows().get(0).order().action(),"F selects targetless run for selected member");check(battle.rows().get(0).order().enemyTarget()==null,"run order has no target");key(manager,KeyEvent.VK_T);same(Action.RUN,battle.rows().get(0).order().action(),"target override cannot turn run into attack");key(manager,KeyEvent.VK_ENTER);same(CombatOutcome.ESCAPED,battle.outcome(),"UI confirmation actually escapes");same(GameState.NATIVE_DIAGNOSTIC,manager.getActiveState(),"escape waits for acknowledgement");check(t.encounterSuspended(),"map remains suspended behind result");render(manager);key(manager,KeyEvent.VK_ENTER);same(GameState.NATIVE_LOCAL_MAP,manager.getActiveState(),"escape acknowledgement returns same area");same(pos,t.position(),"escape return retains exact tile");same(facing,t.facing(),"escape return retains facing");same(new WorldPosition(0,0),c.getWorldPosition(),"escape return retains world anchor");check(t.isExplored(pos.x(),pos.y()),"escape return retains fog");check(!t.encounterSuspended(),"escape releases traversal");same(2,c.party().size(),"UI retains both native members");same(40L,c.gold(),"UI escape grants no gold");same(0L,c.party().get(0).runtime().experience(),"UI escape grants no XP");
        key(manager,KeyEvent.VK_RIGHT);same(GameState.NATIVE_LOCAL_MAP,manager.getActiveState(),"no immediate refight after escape");check(c.activeBattle()==null,"pacing reset remains in effect");
        Path root=Files.createTempDirectory("native-escape-save-");try{String id=AuthoredContentFingerprint.compute(content.maps(),content.npcs(),content.shops());var checkpoint=new NativeSaveManager.Checkpoint(id,c.snapshot(),t.snapshot(),flow.snapshot());var save=root.resolve("escape.pns");NativeSaveManager.save(save,checkpoint,id,content.maps(),content.shops(),p->p.equals(new WorldPosition(0,0)));var loaded=NativeSaveManager.load(save,id,content.maps(),content.shops(),p->p.equals(new WorldPosition(0,0)));same(t.position(),loaded.traversal().position(),"post-escape checkpoint resumes local visit");same(2,loaded.campaign().party().size(),"post-escape checkpoint retains roster");same(40L,loaded.campaign().gold(),"post-escape checkpoint has no phantom reward");same(null,loaded.campaign().activeBattle(),"post-escape checkpoint has no active battle");}finally{try(var files=Files.walk(root)){for(var p:files.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
    }
}
